        if (this.causeProxy != null) {
            this.formatWrapper(sb, this.causeProxy);
            sb.append(WRAPPED_BY_LABEL);
        }
        sb.append(this.toString());
        sb.append(EOL);
        this.formatElements(sb, "", 0, this.throwable.getStackTrace(), this.extendedStackTrace, packages);
        return sb.toString();
    }

